import heapq

def match(orders):
    trades = []
    orders_info = {}  # id -> dict(side, price, qty, seq, status)
    buy_heap = []  # (-price, seq, id) for resting buy orders
    sell_heap = []  # (price, seq, id) for resting sell orders

    seq_counter = 0

    def clean_buy_heap():
        while buy_heap and orders_info[buy_heap[0][2]]['status'] != 'active':
            heapq.heappop(buy_heap)

    def clean_sell_heap():
        while sell_heap and orders_info[sell_heap[0][2]]['status'] != 'active':
            heapq.heappop(sell_heap)

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            info = orders_info.get(oid)
            if info is not None and info['status'] == 'active':
                info['status'] = 'cancelled'
            continue

        # for limit/ioc/market
        oid = order[1]
        side = order[2]

        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        seq = seq_counter
        seq_counter += 1

        remaining = qty

        if side == 'buy':
            # match against sell_heap (lowest price first, then earliest seq)
            while remaining > 0:
                clean_sell_heap()
                if not sell_heap:
                    break
                resting_price, resting_seq, resting_id = sell_heap[0]
                if typ != 'market' and resting_price > price:
                    break
                resting = orders_info[resting_id]
                trade_qty = min(remaining, resting['qty'])
                trades.append([oid, resting_id, resting_price, trade_qty])
                resting['qty'] -= trade_qty
                remaining -= trade_qty
                if resting['qty'] == 0:
                    resting['status'] = 'filled'
                    heapq.heappop(sell_heap)

            if typ == 'limit' and remaining > 0:
                info = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq, 'status': 'active'}
                orders_info[oid] = info
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                if typ == 'limit':
                    orders_info[oid] = {'side': 'buy', 'price': price, 'qty': 0, 'seq': seq, 'status': 'filled'}
                else:
                    orders_info[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq, 'status': 'discarded'}

        else:  # side == 'sell'
            # match against buy_heap (highest price first, then earliest seq)
            while remaining > 0:
                clean_buy_heap()
                if not buy_heap:
                    break
                neg_price, resting_seq, resting_id = buy_heap[0]
                resting_price = -neg_price
                if typ != 'market' and resting_price < price:
                    break
                resting = orders_info[resting_id]
                trade_qty = min(remaining, resting['qty'])
                trades.append([resting_id, oid, resting_price, trade_qty])
                resting['qty'] -= trade_qty
                remaining -= trade_qty
                if resting['qty'] == 0:
                    resting['status'] = 'filled'
                    heapq.heappop(buy_heap)

            if typ == 'limit' and remaining > 0:
                info = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq, 'status': 'active'}
                orders_info[oid] = info
                heapq.heappush(sell_heap, (price, seq, oid))
            else:
                if typ == 'limit':
                    orders_info[oid] = {'side': 'sell', 'price': price, 'qty': 0, 'seq': seq, 'status': 'filled'}
                else:
                    orders_info[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq, 'status': 'discarded'}

    return trades

